const ZONE = 'America/Chicago';
const raw = ($('Normalize').first().json.slot || '').toString().trim();

function parseSlot(input) {
  if (!input) return null;
  let dt = DateTime.fromISO(input, { zone: ZONE });
  if (dt.isValid) return dt;
  let s = input.replace(/\u2013|\u2014/g, '-').replace(/\s+/g, ' ').trim();
  s = s.replace(/\b(CDT|CST|CT|EDT|EST|ET|MDT|MST|MT|PDT|PST|PT|Central( Time)?|Eastern( Time)?|Mountain( Time)?|Pacific( Time)?)\.?$/i, '').trim();
  s = s.replace(/(\d{1,2})(st|nd|rd|th)\b/gi, '$1');
  s = s.replace(/\b([ap])\.?\s?m\.?/gi, (m, x) => x.toUpperCase() + 'M');
  const wd = s.match(/^(next\s+)?(sun|mon|tue|tues|wed|wednes|thu|thur|thurs|fri|sat|satur)(day)?\b,?\s*/i);
  if (wd) s = s.slice(wd[0].length).trim();
  const rel = s.match(/\b(today|tomorrow)\b/i);
  const tm = s.match(/(\d{1,2})(?::(\d{2}))?\s*(AM|PM)/i);
  const mkTime = (base) => { let h = parseInt(tm[1], 10) % 12; if (/pm/i.test(tm[3])) h += 12; return base.set({ hour: h, minute: tm[2] ? parseInt(tm[2], 10) : 0, second: 0, millisecond: 0 }); };
  if (rel && tm) {
    let base = DateTime.now().setZone(ZONE).startOf('day');
    if (/tomorrow/i.test(rel[1])) base = base.plus({ days: 1 });
    return mkTime(base);
  }
  const formats = ["MMMM d, yyyy 'at' h:mm a", "MMMM d, yyyy 'at' h a", "MMMM d 'at' h:mm a", "MMMM d 'at' h a", "MMMM d, yyyy h:mm a", "MMMM d, yyyy h a", "MMMM d h:mm a", "MMMM d h a", "MMM d, yyyy 'at' h:mm a", "MMM d, yyyy 'at' h a", "MMM d 'at' h:mm a", "MMM d 'at' h a", "MMM d, yyyy h:mm a", "MMM d, yyyy h a", "MMM d h:mm a", "MMM d h a", "M/d/yyyy h:mm a", "M/d h:mm a", "M/d h a"];
  for (const f of formats) {
    dt = DateTime.fromFormat(s, f, { zone: ZONE });
    if (dt.isValid) return dt;
  }
  if (wd && tm) {
    const key = wd[2].toLowerCase().slice(0, 3);
    const map = { sun: 7, mon: 1, tue: 2, wed: 3, thu: 4, fri: 5, sat: 6 };
    const target = map[key];
    if (target) {
      const nowW = DateTime.now().setZone(ZONE);
      let cand = mkTime(nowW.startOf('day').plus({ days: (target - nowW.weekday + 7) % 7 }));
      if (cand <= nowW) cand = cand.plus({ days: 7 });
      else if (wd[1] && (target - nowW.weekday + 7) % 7 === 0) cand = cand.plus({ days: 7 });
      return cand;
    }
  }
  if (tm && s.replace(tm[0], '').trim() === '') {
    const nowT = DateTime.now().setZone(ZONE);
    let cand = mkTime(nowT.startOf('day'));
    if (cand <= nowT) cand = cand.plus({ days: 1 });
    return cand;
  }
  return null;
}

const resp = $json;
let free = [];
for (const k of Object.keys(resp)) {
  if (k === 'traceId') continue;
  const v = resp[k];
  if (v && Array.isArray(v.slots)) free = free.concat(v.slots);
}
const nowZ = DateTime.now().setZone(ZONE);
const freeDt = free.map(s => DateTime.fromISO(s).setZone(ZONE)).filter(d => d.isValid && d > nowZ);
freeDt.sort((a, b) => a.toMillis() - b.toMillis());
const fence = d => d.weekday <= 5 && d.hour >= 8 && d.hour < 18;
const fenced = freeDt.filter(fence);
const fmt = "cccc, LLL d 'at' h:mm a";
const human = d => d.toFormat(fmt) + ' CT';

function out(o) { return [{ json: o }]; }

if (!raw) {
  if (!fenced.length) return out({ bookable: false, reason: 'no_slots_available', requested: '', nearest_slot: '', nearest_slot_human: '', alternatives: [] });
  const pick = fenced[0];
  return out({ bookable: true, mode: 'auto', slot_final: pick.toISO(), slot_end: pick.plus({ minutes: 20 }).toISO(), slot_human_ct: human(pick) });
}

let requestedDt = parseSlot(raw);
if (requestedDt && requestedDt < nowZ.minus({ hours: 1 })) {
  const bumped = requestedDt.plus({ years: 1 });
  if (bumped > nowZ) requestedDt = bumped;
}

if (!requestedDt || !requestedDt.isValid) {
  const near = fenced[0];
  return out({ bookable: false, reason: 'could_not_parse_time', requested: raw, nearest_slot: near ? near.toISO() : '', nearest_slot_human: near ? human(near) : '', alternatives: fenced.slice(1, 3).map(human) });
}

const reqMin = Math.round(requestedDt.toMillis() / 60000);
const match = fenced.find(d => Math.round(d.toMillis() / 60000) === reqMin);
if (match) {
  return out({ bookable: true, mode: 'requested', slot_final: match.toISO(), slot_end: match.plus({ minutes: 20 }).toISO(), slot_human_ct: human(match) });
}

const inFence = fence(requestedDt) && requestedDt > nowZ;
const reason = inFence ? 'slot_taken' : 'outside_service_hours';
let near = null, bestScore = Infinity;
for (const d of fenced) {
  const diff = d.toMillis() - requestedDt.toMillis();
  const score = Math.abs(diff) - (diff >= 0 ? 1 : 0);
  if (score < bestScore) { bestScore = score; near = d; }
}
const alts = fenced.filter(d => !near || d.toMillis() !== near.toMillis()).slice(0, 2).map(human);
return out({ bookable: false, reason, requested: raw, requested_parsed_ct: human(requestedDt), nearest_slot: near ? near.toISO() : '', nearest_slot_human: near ? human(near) : '', alternatives: alts });

